@namespace sv_05ed5209f07a442f84f1a5b28be824a8.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm
                Name="@reference.Name"
                Relationship="@reference.Relationship"
                Email="@reference.Email"
                Phone="@reference.Phone"
                CanRemove="@(References.Count > 2)"
                OnChanged="data => UpdateReference(index, data)"
                OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private string? ValidationError;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        var r = References[index];
        r.Name = data.Name;
        r.Relationship = data.Relationship;
        r.Email = data.Email;
        r.Phone = data.Phone;
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        var first = References[0];
        if (string.IsNullOrWhiteSpace(first.Name) || string.IsNullOrWhiteSpace(first.Email))
        {
            ValidationError = "At least the first reference must have a name and email.";
            return;
        }
        await OnNext.InvokeAsync(References);
    }
}

