@page "/apply"
@using sv_05ed5209f07a442f84f1a5b28be824a8.Models
@using sv_05ed5209f07a442f84f1a5b28be824a8.Components.Pages.Apply
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" CompletedSteps="@completedSteps" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep
                FullName="@fullName"
                Email="@email"
                Phone="@phone"
                Address="@address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;
        case 2:
            <WorkHistoryStep
                Entries="@workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <ReferencesStep
                References="@references"
                OnNext="HandleReferencesNext"
                OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => GoToStep(3)" />
            break;
        case 5:
            <ReviewStep
                FullName="@fullName"
                Email="@email"
                Phone="@phone"
                Address="@address"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                OnEditStep="GoToStep"
                OnBack="() => GoToStep(4)"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        fullName = result.FullName;
        email = result.Email;
        phone = result.Phone;
        address = result.Address;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(4);
        currentStep = 5;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(fullName, email, phone, address);
        var work = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());
        var refs = references
            .Where(r => !string.IsNullOrWhiteSpace(r.Name))
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, work, refs, coverLetter);

        var id = await ApplicationService.SubmitApplicationAsync(application);
        completedSteps.Add(5);
        return id;
    }
}

